    let mut j: i32 = 0;
    let mut dx: i32 = 0;
    let mut dy: i32 = 0;
    let mut le: i32 = 0;
    let mut lbest: i32 = 0;
    let mut theta: i32 = 0;
    let mut perim: i32 = 0;
    let mut off: i32 = 0;
