    let mut dy: i32 = 0;
    let mut gx: i32 = 0;
    let mut gy: i32 = 0;
    let mut hmax: i32 = 0;
    let mut wmax: i32 = 0;
    let mut ra: i32 = 0;
    let mut rb: i32 = 0;
    let mut lo: i32 = 0;
    let mut hi: i32 = 0;
    let mut rows: i32 = 0;
    let mut k: i32 = 0;
    let mut e: i32 = 0;
    let mut row: i32 = 0;
    let mut alpha: i32 = 0;
    let mut th: i32 = 0;
    let mut co: i32 = 0;
    let mut si: i32 = 0;
    let mut x0: i32 = 0;
    let mut y0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y1: i32 = 0;
    let mut hbar: i32 = 0;
    let mut pass: i32 = 0;
    let mut m: i32 = 0;
    let mut slope: i64 = 0;
    let mut icpt: i64 = 0;
    let mut hsum: i32 = 0;
    let mut gsum: i32 = 0;
    let mut rms: i32 = 0;
    let mut evr: i32 = 0;
    let mut u0: i32 = 0;
    let mut u1: i32 = 0;
    let mut v0: i32 = 0;
    let mut v1: i32 = 0;
    let mut px0: i32 = 0;
